<?php
$adminTitle='Produktet';$adminActive='products';require __DIR__.'/_header.php';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['delete'])){verify_csrf();$id=(int)$_POST['delete'];$stmt=$db->prepare('SELECT image FROM products WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$image=$stmt->get_result()->fetch_assoc()['image']??'';$del=$db->prepare('DELETE FROM products WHERE id=?');$del->bind_param('i',$id);try{$del->execute();if($image&&is_file(__DIR__.'/../uploads/'.basename($image)))unlink(__DIR__.'/../uploads/'.basename($image));flash('success','Produkti u fshi.');}catch(mysqli_sql_exception $e){flash('error','Produkti ka porosi dhe nuk mund të fshihet. Çaktivizoje në vend të fshirjes.');}redirect('admin/products.php');}
$products=$db->query('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC');
?>
<div class="admin-toolbar"><a class="button button-dark" href="product-form.php">+ Shto produkt</a></div><div class="table-card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Produkti</th><th>Kategoria</th><th>Çmimi</th><th>Stoku</th><th>Statusi</th><th>Veprime</th></tr></thead><tbody><?php while($p=$products->fetch_assoc()): ?><tr><td><div class="cart-product"><img class="thumb" src="<?= e(product_image($p['image'])) ?>"><strong><?= e($p['name']) ?></strong></div></td><td><?= e($p['category_name']) ?></td><td><?= money((float)$p['price']) ?></td><td><?= $p['stock'] ?></td><td><span class="status <?= $p['is_active']?'completed':'cancelled' ?>"><?= $p['is_active']?'Aktiv':'Joaktiv' ?></span></td><td><div class="admin-actions"><a class="mini-button" href="product-form.php?id=<?= $p['id'] ?>">Ndrysho</a><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><button class="mini-button danger" name="delete" value="<?= $p['id'] ?>" data-confirm="A jeni të sigurt që doni ta fshini produktin?">Fshi</button></form></div></td></tr><?php endwhile; ?></tbody></table></div></div>
